import{_ as t}from"./chunks/z-stack-time-laps-navigation.DWNnv26e.js";import{_ as a,c as o,o as n,ag as r}from"./chunks/framework.DZ_cNctr.js";const s="/docs/screenshots/z-projection-controls.png",i="/docs/screenshots/z-projection-compare-max.png",h="/docs/screenshots/z-projection-compare-mean.png",l="/docs/screenshots/z-projection-in-action.png",y=JSON.parse('{"title":"Z-Projection","description":"Flatten a Z-stack into one image with maximum, mean or minimum intensity projection. Choose a Z-range, keep large stacks fast, and know which projection answers which question.","frontmatter":{"title":"Z-Projection","description":"Flatten a Z-stack into one image with maximum, mean or minimum intensity projection. Choose a Z-range, keep large stacks fast, and know which projection answers which question."},"headers":[],"relativePath":"guides/z-projection.md","filePath":"guides/z-projection.md"}'),c={name:"guides/z-projection.md"};function p(d,e,u,g,m,f){return n(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="z-projection" tabindex="-1">Z-Projection <a class="header-anchor" href="#z-projection" aria-label="Permalink to &quot;Z-Projection&quot;">​</a></h1><p>A Z-stack is a set of focal planes through a specimen. Scrolling them one at a time is how you inspect a volume, but it is a poor way to see a whole structure at once: a nucleus that spans thirty planes is never fully in focus in any single one.</p><p>A projection collapses a range of planes into one image by combining them pixel by pixel. Everything in the range contributes, so the object appears whole.</p><p><img src="'+s+'" alt="Z-Projection panel: mode dropdown set to Max Intensity, Start and End range sliders, Around Z button, and the Projected / Off buttons" style="max-width:412px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><h2 id="which-projection-answers-which-question" tabindex="-1">Which projection answers which question <a class="header-anchor" href="#which-projection-answers-which-question" aria-label="Permalink to &quot;Which projection answers which question&quot;">​</a></h2><p>Each mode answers a different question. The right one brings out detail a single plane cannot show.</p><p><strong>Maximum</strong> takes the brightest value at each pixel across the range. This is the default for a reason: fluorescent objects are bright against a dark background, so the brightest plane at any point is the one where the object sits. Use it for nuclei, puncta, filaments, anything sparse and bright. It is also the least forgiving of noise, because a single hot pixel in any plane survives into the result.</p><p><strong>Mean</strong> averages across the range. Noise averages down while real signal stays, so this is the one to reach for when the stack is noisy or the signal is faint and spread out. The cost is contrast: a small bright object sitting in five of two hundred planes is diluted by the other one hundred and ninety five.</p><p><strong>Minimum</strong> takes the darkest value. This is the one for brightfield or phase, where the objects of interest are darker than their surroundings. In fluorescence, reach for maximum or mean instead.</p><p>If you are unsure, start with maximum and switch to mean if the result looks grainy.</p><h3 id="the-same-field-both-ways" tabindex="-1">The same field, both ways <a class="header-anchor" href="#the-same-field-both-ways" aria-label="Permalink to &quot;The same field, both ways&quot;">​</a></h3><p>Both of these are the same 51-plane slab, same field, same zoom. Only the mode differs. That is the range the panel offers by default at this plane, so it is what <strong>Compute</strong> gives you without touching a slider. The mean is shown inverted, the easiest way to read a dim, diffuse result on screen.</p><div style="display:flex;gap:1rem;flex-wrap:wrap;margin:1rem 0;"><figure style="flex:1 1 320px;margin:0;"><img src="'+i+'" alt="Maximum intensity projection of a 51-plane slab: every nucleus crisp and separate, bright cyan on black, with chromatin texture visible inside each one" style="width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;"><figcaption style="font-size:0.85em;color:var(--vp-c-text-2);margin-top:0.4rem;"><strong>Maximum.</strong> Edges stay sharp and every nucleus reads as its own object. <a href="https://find-nuclei.github.io/?url=https://uk1s3.embassy.ebi.ac.uk/idr/zarr/v0.5/idr0062A/6001240_labels.zarr&amp;z=118&amp;c=0:on:FFFFFF:78:4750,1:on:008080:41:1366&amp;zm=1.73&amp;xy=136,138&amp;cm=C&amp;inv=f&amp;bg=%23ffffff&amp;pj=max:93:143&amp;l=" target="_blank" rel="noopener noreferrer">Open this view</a></figcaption></figure><figure style="flex:1 1 320px;margin:0;"><img src="'+h+'" alt="Mean projection of the same slab, inverted: the same nuclei rendered soft and pale on white, with overlapping nuclei showing as darker patches" style="width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;"><figcaption style="font-size:0.85em;color:var(--vp-c-text-2);margin-top:0.4rem;"><strong>Mean.</strong> Noise falls away, and so does contrast: nuclei blur into their neighbours. <a href="https://find-nuclei.github.io/?url=https://uk1s3.embassy.ebi.ac.uk/idr/zarr/v0.5/idr0062A/6001240_labels.zarr&amp;z=118&amp;c=0:on:FFFFFF:9:1249,1:on:FF0000:35:664&amp;zm=1.73&amp;xy=136,138&amp;cm=C&amp;inv=t&amp;bg=%23ffffff&amp;pj=mean:93:143&amp;l=" target="_blank" rel="noopener noreferrer">Open this view</a></figcaption></figure></div><p>On this dataset maximum wins, and the pair shows why: the nuclei are bright, sparse objects against a dark background, which is exactly what maximum is for. Reach for mean when the signal is faint and spread out and the noise is what you are fighting.</p><p>Both links carry the mode and range in the URL, so anything you set up here can be handed to someone else exactly as you see it.</p><h2 id="choosing-the-z-range" tabindex="-1">Choosing the Z-range <a class="header-anchor" href="#choosing-the-z-range" aria-label="Permalink to &quot;Choosing the Z-range&quot;">​</a></h2><p>A tighter range is usually the better choice. A cell monolayer sitting in the middle of a two hundred plane acquisition gains everything from the planes it actually occupies, and waits on the empty ones above and below.</p><p><img src="'+t+'" alt="Z-slider and time-lapse navigation below the viewer" style="max-width:411px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><p>The panel starts on <strong>Off</strong>. Pick a mode and the range sliders and the compute button appear, with the range already covering twenty five planes either side of the plane you are on.</p><p>Three ways to set the range:</p><ul><li><strong>Drag the Start and End sliders</strong> to any range you like.</li><li><strong>Around Z</strong> resets the range to that default, recentred on whichever plane you are on now and clamped to the ends of the stack. This is the fastest way to project just the part you are already looking at.</li><li><strong>Full</strong> returns to the whole stack. It only appears on stacks of 200 planes or fewer. Above that the button is gone and the sliders are the only way, which is what the worked example below runs into.</li></ul><div class="warning custom-block"><p class="custom-block-title">Changes are not live</p><p>Adjusting the mode or the range stages the change. Nothing is recomputed until you press <strong>Compute</strong>. Once it has run the button reads <strong>Projected</strong> and greys out, so the label tells you whether what you are looking at is up to date. Press <strong>Off</strong> to drop back to single-plane viewing. This is deliberate: on a large stack, recomputing on every slider movement would make the control unusable.</p></div><h2 id="large-stacks" tabindex="-1">Large stacks <a class="header-anchor" href="#large-stacks" aria-label="Permalink to &quot;Large stacks&quot;">​</a></h2><p>Projection is computed in the browser over every plane in the range, so cost grows with the number of planes.</p><table tabindex="0"><thead><tr><th>Planes in range</th><th>What the viewer tells you</th></tr></thead><tbody><tr><td>Up to 100</td><td>nothing, it is fast</td></tr><tr><td>101 to 200</td><td>&quot;May take a moment to compute&quot;</td></tr><tr><td>Over 200</td><td>a warning that it may be slow or time out, with a suggestion to narrow the range</td></tr></tbody></table><p>The warnings are advice, not a block: you can project the full stack anyway. But if you are on a remote dataset over a slow connection, every plane in the range is chunks that have to arrive first, and <strong>Around Z</strong> will usually get you the same biological answer in a fraction of the time.</p><p>The control appears for any image with more than one Z-plane.</p><h2 id="a-worked-example" tabindex="-1">A worked example <a class="header-anchor" href="#a-worked-example" aria-label="Permalink to &quot;A worked example&quot;">​</a></h2><p><img src="'+l+'" alt="The viewer showing the 6001240 confocal stack after projection: every nucleus whole and in focus, with the Z-Projection panel open on the right, Max Intensity selected, the range set to the full 0 to 235, the 236-slice warning visible, and the compute button reading Projected" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><p><strong><a href="https://find-nuclei.github.io/?url=https://uk1s3.embassy.ebi.ac.uk/idr/zarr/v0.5/idr0062A/6001240_labels.zarr&amp;z=118&amp;c=0:on:FFFFFF:7:6312,1:on:00FFFF:26:1926&amp;zm=1.73&amp;xy=136,138&amp;cm=C&amp;inv=f&amp;pj=none&amp;l=" target="_blank" rel="noreferrer">Open the 6001240 stack in the viewer</a></strong>, with both channels already set to the colours and intensity windows used in the screenshot above. It is a confocal stack of nuclei, 236 planes deep, and it shows the difference clearly. It is in the Examples gallery too, as &quot;6001240 Labels&quot;.</p><p>The link sets the projection to off on purpose, so it opens on a single plane. That is the point of step one.</p><ol><li>Let it load and look at the Z-slider. You are on one plane out of 236, and most nuclei are cut through the middle or out of focus entirely.</li><li>Drag the Z-slider slowly. Individual nuclei come into focus and drop out again. This is the volume you are trying to see all at once.</li><li>Set <strong>Z-Projection</strong> to <strong>Max Intensity</strong>. The range appears, already covering fifty one of the 236 planes. Press <strong>Compute</strong>. Every nucleus in that slab is now whole and in focus.</li><li>Now try the whole stack: drag <strong>Start</strong> to 0 and <strong>End</strong> to 235. A warning appears, because 236 planes is over the recommended range. Press <strong>Compute</strong> again. It takes noticeably longer, and nuclei from every depth are now piled on top of each other. This is the state in the screenshot above.</li><li>Press <strong>Around Z</strong> to snap back to fifty one planes, then <strong>Compute</strong>. It computes far faster, and for counting nuclei in one layer it is the better view, because nuclei from other depths are no longer overlapping the ones you care about.</li><li>Switch to <strong>Mean</strong> and press <strong>Compute</strong>. The image is smoother and dimmer. On this dataset maximum is the better choice, which is exactly the comparison worth making on your own data.</li></ol><p>Step five is the habit worth keeping. Projecting everything is the obvious move and rarely the useful one.</p><h2 id="related-guides" tabindex="-1">Related guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to &quot;Related guides&quot;">​</a></h2><ul><li><a href="./channels.html">Channels</a>: contrast and colour, which interact with how a projection looks</li><li><a href="./../getting-started.html">Getting Started</a>: Z-stack navigation and the rest of the viewer</li><li><a href="./../sample-data.html">Sample Data and Credits</a>: where the example datasets come from</li></ul>',35)])])}const v=a(c,[["render",p]]);export{y as __pageData,v as default};
